def semver_sort(versions):
    def parse_version(v):
        # Split build metadata first
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            base, prerelease = v.split('-', 1)
        else:
            base = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            pre_ids = prerelease.split('.')
            pre_parts = []
            for ident in pre_ids:
                if ident.isdigit():
                    pre_parts.append((0, int(ident)))
                else:
                    pre_parts.append((1, ident))
        else:
            pre_parts = None

        return (major, minor, patch, pre_parts)

    def sort_key(v_with_index):
        v, index = v_with_index
        major, minor, patch, pre_parts = parse_version(v)

        # For stable sort, versions with pre-release sort before those without
        # If pre_parts is None, use a tuple that sorts after any list
        if pre_parts is None:
            pre_key = (1, [])
        else:
            pre_key = (0, pre_parts)

        return (major, minor, patch, pre_key, index)

    # Create list of (version, original_index) to maintain stable sort
    indexed = [(v, i) for i, v in enumerate(versions)]
    sorted_indexed = sorted(indexed, key=sort_key)
    return [v for v, _ in sorted_indexed]

